    add(11,'parameter learning','Author sequential mean/loading/residual updates from responsibility-weighted latent moments.','AUTHOR_CODE','Sec III refers to EM but gives no update formulas',core('def _EM_per_component'))
    add(12,'EM','EM-style algorithm exactly as original author; no substituted textbook updates.','BOTH','Sec III, citation [11]',core('def run_em'))
