    add(14,'M step','mu_new=sum r(x-W_old z)/Nk; W_new=sum r(x-mu_new)z^H [sum r Ezz^H]^-1; residual uses W_old z, then author floor/isotropization; pi=Nk/N.','AUTHOR_CODE','EM update details UNSPECIFIED',core('lambdalatents = '),'Do not replace old Wz in residual with new Wz; do not assert strict likelihood monotonicity.')
    add(15,'constraints','Psi entries clipped to 1e-6 at M-step before isotropic averaging. No clipping at initialization in 2023; no responsibility floor at rs_clip=0.0.','AUTHOR_CODE','Regularization details UNSPECIFIED',core('self._psis[k] = np.clip'))
