    add(26,'real expansion','concat(Re,Im) without sqrt(2), split half then Re+i Im; not a doubled real Gaussian training model.','AUTHOR_CODE','Not used as model representation','reference/sp_u12b5a/paper_period/cplx-mfa/utils.py:4')
    add(27,'normalization centering','Paper measurements globally normalized E||h||^2=D; author fit performs no scaling/precentering. Project retains physical units and learned component means.','BOTH','Sec II measured data normalization',core('def fit(self, data)'),'Fixed-unit adaptation, not a numerical replication of paper figures; fixed 1e-6 author floor retained in these units.')
    add(28,'inverse normalization','None in author code or project; output remains in same physical units as clean training data.','AUTHOR_CODE','Paper global experimental normalization convention',est('return h_est'))
    add(29,'numerical linear algebra','Author scipy.linalg.inv for latent moment; numpy pinv for Woodbury inner and noisy observation covariance; Psi floor 1e-6. Preserve all; no added ridge/fallback.','AUTHOR_CODE','Sec IV Woodbury, Eq (15)',core('inv_inner = '))
    add(30,'paper/code differences','Paper identity observation special case, author general A; paper isotropic numerical setting selected by PPCA flag; constructor hard-selection default explicitly overridden by documented float full-mixture API. Paper EM/init details unspecified; original code is authoritative.','BOTH','Secs II-V',est('n_summands_or_proba: float = 1'))
    policy=dict(status='FROZEN',reference='2023 paper-period original author commits',PPCA=True,lock_psis=False,rs_clip=0.0,max_condition_number=1e6,maxiter=100,tol=1e-4,verbose=False,outer_model_fits=1,outer_restarts=0,KMeans_n_init=1,KMeans_init='k-means++',KMeans_seed='Recorded NumPy legacy MT19937 initialization seed (random_state=None follows existing seeded global state)',loading_and_weight_seed='Same recorded initialization seed, consumed sequentially after KMeans',seed_control='Temporarily save global RandomState, seed it once, execute original author fit, restore state; no unrecorded global randomness',training_seed='Same as initialization seed: EM has no additional stochastic draws',restart_seed=None,best_run_selection='NOT_APPLICABLE',future_formal_seeds='Must be allocated and frozen by future B5B before training; toy seeds never select policy',stopping='i > 5 and abs((newL - previousL)/newL) < 1e-4',maxiter_exhaustion='Original author warning retained; future formal convergence gate STOP, no rescue',source=core('maxiter=100'),basis='AUTHOR_CODE defaults; PPCA specialization from PAPER Sec V')
