    csvout('evidence_matrix',evidence)
    contract=dict(online_allowed=['received owner-pilot symbols','known owner symbols and pilot geometry/order','known source-referenced complex noise variance'],online_forbidden=['target clean CSI','target covariance','condition/environment/speed/delay labels','future frames'],tensor_axes=['Rx','Tx','subcarrier','OFDM symbol'],tensor_shape=[2,2,64,16],order='C',flat_index='(((rx*2+tx)*64+k)*16+t)',full_tensor_dimension=4096,working_joint_dimension=4032,pilot_dimension=64,data_dimension=3968,excluded_muted_link_coordinates=64,working_order='Sorted union of existing pilot indices and existing data mask, preserving full C-order',inverse_mapping='Full4096 vector roundtrip exact; working4032 vector needs explicit 64-coordinate sidecar to reconstruct full tensor, not falsely bijective alone',posterior_output='data coordinates in existing C-order',normalization='NONE; physical units, learned means; no Source centering or target-power scaling',pilot_model='raw_owner_i=x_owner_i*h_i+w_i; y_i=raw_owner_i/x_owner_i; A picks h_i; unit modulus => Cn=sigma2 I',source_power_reference=9.941134822523972,future_only=dict(origins=3,trajectories_per_origin=500,train_per_origin=400,validation_per_origin=100,split_unit='trajectory',K=[1,2,4],latent_dim=[4,8,16],validation_SNR_dB=[10,20],metric='macro-average of six prepared-origin data-domain linear pooled NMSE cells',retrain='selected configuration on all 1500 preparation trajectories',formal_evaluation='5x7 grid, identical B2 trajectories, only after model frozen',executed=False))
    report('interface_contract',contract)
    history=read(OUT/'historical_reference.json');metadata=read(ROOT/'outputs/sp_u12b5a_mfa_reference_metadata.json')
    metadata.update(selected_reference=dict(version='2023 paper-period',repositories=history,selection_reason='Latest available 2023 snapshots; estimator gitlink exactly pins selected core; 2026 algorithm/RNG/safety changes explicitly excluded'),paper_period_code='FOUND_AND_SELECTED',HEAD_2026_used_for_training=False)
